import { useCallback, useEffect, useRef, useState } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { supabase } from '@/integrations/supabase/client';

export type CredentialTarget = {
  id: string; user_id: string; organization_id: string | null;
  login: string | null; role: string | null; full_name: string | null; created_at: string;
};
type Request = {
  scope: number; version: number; target: string; row: string;
  controller: AbortController; timer: number | null;
};
type Snapshot = { scope: number; target: string; status: 'loading' | 'revealed' | 'failed'; version: number };
type Secret = { scope: number; target: string; row: string; value: string };
type SingleRead = { abortSignal(signal: AbortSignal): PromiseLike<{ data: unknown; error: unknown }> };
const readSingle = supabase.rpc.bind(supabase) as unknown as
  (name: 'get_decrypted_student_password', args: { p_user_id: string }) => SingleRead;
const isUUID = (value: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const rowKey = (row: CredentialTarget) => JSON.stringify([
  row.id, row.user_id, row.organization_id, row.login, row.role, row.full_name, row.created_at,
]);
const isPassword = (value: unknown): value is string => typeof value === 'string'
  && value.trim().length > 0 && value.length <= 4096 && !value.includes('\0')
  && !/^ENC:/i.test(value) && !/^[\s•*]+$/.test(value);

/** Explicit one-row display only. The existing RPC repeats server authority. */
export function useExplicitUserCredential(rows: readonly CredentialTarget[], viewKey: string) {
  const { user, session, userRole, loading, authError } = useAuth();
  const actor = user?.id ?? null;
  const ready = !!actor && session?.user?.id === actor && userRole === 'admin'
    && !loading && !authError && typeof session?.expires_at === 'number'
    && session.expires_at * 1000 > Date.now();
  const key = JSON.stringify([actor, ready, viewKey, rows.map(rowKey)]);
  const scope = useRef({ key, session, generation: 0 });
  // A→B→A and renewed sessions cannot reuse an earlier request generation.
  if (scope.current.key !== key || scope.current.session !== session) {
    scope.current = { key, session, generation: scope.current.generation + 1 };
  }
  const generation = scope.current.generation;
  const sequence = useRef(0);
  const pending = useRef<Request | null>(null);
  const secret = useRef<Secret | null>(null);
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const currentRows = useRef(rows);
  currentRows.current = rows;
  const eligible = (id: string) => currentRows.current.find(row =>
    isUUID(id) && row.user_id === id && row.role === 'student' && typeof row.login === 'string' && !!row.login);
  const currentScope = () => ready && document.visibilityState === 'visible' && scope.current.key === key
    && scope.current.session === session && scope.current.generation === generation
    && typeof session?.expires_at === 'number' && session.expires_at * 1000 > Date.now();

  const clear = useCallback((onlyUserId?: string) => {
    if (onlyUserId && secret.current?.target !== onlyUserId && pending.current?.target !== onlyUserId) return;
    sequence.current++;
    const previous = pending.current;
    pending.current = null;
    if (previous) {
      previous.controller.abort();
      if (previous.timer !== null) window.clearTimeout(previous.timer);
    }
    secret.current = null;
    setSnapshot(null);
  }, []);

  useEffect(() => {
    // Plaintext is never stored in the users list or hidden React state.
    secret.current = null;
    setSnapshot(null);
    const stale = pending.current;
    if (stale && stale.scope !== generation) {
      pending.current = null;
      stale.controller.abort();
      if (stale.timer !== null) window.clearTimeout(stale.timer);
    }
    const onHidden = () => { if (document.visibilityState !== 'visible') clear(); };
    const onBlur = () => clear();
    window.addEventListener('blur', onBlur);
    document.addEventListener('visibilitychange', onHidden);
    const expiry = ready && typeof session?.expires_at === 'number'
      ? window.setTimeout(clear, Math.min(2147483647, Math.max(0, session.expires_at * 1000 - Date.now())))
      : null;
    return () => {
      window.removeEventListener('blur', onBlur);
      document.removeEventListener('visibilitychange', onHidden);
      if (expiry !== null) window.clearTimeout(expiry);
      if (secret.current?.scope === generation) secret.current = null;
      const request = pending.current;
      if (request?.scope === generation) {
        pending.current = null;
        request.controller.abort();
        if (request.timer !== null) window.clearTimeout(request.timer);
      }
    };
  }, [key, session, generation, ready, clear]);

  const toggle = async (userId: string) => {
    if (!currentScope() || !userId) { clear(); return; }
    const row = eligible(userId);
    if (!row) { clear(); return; }
    if (secret.current?.scope === generation && secret.current.target === userId
      || pending.current?.scope === generation && pending.current.target === userId) { clear(); return; }
    clear();
    const request: Request = {
      scope: generation, version: ++sequence.current, target: userId,
      row: rowKey(row), controller: new AbortController(), timer: null,
    };
    const isCurrent = () => currentScope() && pending.current === request
      && request.version === sequence.current && !request.controller.signal.aborted
      && !!eligible(userId) && rowKey(eligible(userId)!) === request.row;
    pending.current = request;
    setSnapshot({ scope: generation, target: userId, status: 'loading', version: request.version });
    request.timer = window.setTimeout(() => {
      const announce = isCurrent();
      // A deadline always aborts its physical fetch, even after context becomes invalid.
      request.controller.abort();
      if (pending.current !== request) return;
      pending.current = null; sequence.current++; secret.current = null;
      setSnapshot(previous => announce
        ? { scope: generation, target: userId, status: 'failed', version: request.version }
        : previous?.version === request.version ? null : previous);
    }, 12000);
    try {
      const { data, error } = await readSingle('get_decrypted_student_password', {
        p_user_id: userId,
      }).abortSignal(request.controller.signal);
      if (!isCurrent()) return;
      if (error || !isPassword(data)) throw Error('CREDENTIAL_UNAVAILABLE');
      secret.current = { scope: generation, target: userId, row: request.row, value: data };
      setSnapshot({ scope: generation, target: userId, status: 'revealed', version: request.version });
    } catch {
      if (isCurrent()) {
        secret.current = null;
        setSnapshot({ scope: generation, target: userId, status: 'failed', version: request.version });
      }
    } finally {
      if (request.timer !== null) window.clearTimeout(request.timer);
      if (pending.current === request) pending.current = null;
    }
  };

  const passwordFor = (userId: string): string | null => {
    const value = secret.current;
    const row = eligible(userId);
    return currentScope() && value?.scope === generation && value.target === userId
      && row && value.row === rowKey(row) && isPassword(value.value) ? value.value : null;
  };
  const currentSnapshot = currentScope() && snapshot?.scope === generation
    && !!eligible(snapshot.target) ? snapshot : null;
  return {
    toggle, clear, passwordFor,
    pendingUserId: currentSnapshot?.status === 'loading' ? currentSnapshot.target : null,
    failedVersion: currentSnapshot?.status === 'failed' ? currentSnapshot.version : null,
  };
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Search, Users, Shield, Building2, GraduationCap } from "lucide-react";
import { toast } from "sonner";
import { SigmaSpinner } from "@/components/ui/SigmaSpinner";
import { TableSkeleton } from "@/components/shared/TableSkeleton";
import { EmptyState } from "@/components/shared/EmptyState";
import { UserTableRow, type UserWithRole } from "./users/UserTableRow";
import { useExplicitUserCredential } from "@/hooks/useExplicitUserCredential";


export function UsersManager() {
  const [users, setUsers] = useState<UserWithRole[]>([]);
  const [organizations, setOrganizations] = useState<{ id: string; name: string }[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [visibleCount, setVisibleCount] = useState(10);
  const [deleteUser, setDeleteUser] = useState<UserWithRole | null>(null);
  const navigate = useNavigate();

  const viewAsStudent = (user: UserWithRole) => {
    localStorage.setItem('adminViewAsStudent', JSON.stringify({
      userId: user.user_id,
      name: user.full_name || user.email || 'Ученик',
      orgName: user.organization_name || '' }));
    navigate('/student');
  };

  const togglePasswordVisibility = (userId: string) => { void credentials.toggle(userId); };

  const copyCredentials = async (userId: string) => {
    const row = displayedUsers.find(user => user.user_id === userId);
    const password = credentials.passwordFor(userId);
    if (!row?.login || !password) return;
    try {
      await navigator.clipboard.writeText(`Логин: ${row.login}\nПароль: ${password}`);
      toast.success("Скопировано", { description: "Логин и пароль скопированы в буфер обмена" });
    } catch {
      toast.error("Не удалось скопировать учётные данные");
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    credentials.clear();
    try {
      // Fetch profiles with roles (exclude generated_password - it's encrypted)
      const { data: profiles, error: profilesError } = await supabase
        .from("profiles")
        .select("id, user_id, full_name, email, avatar_url, organization_id, login, company_id, created_at")
        .order("created_at", { ascending: false });

      if (profilesError) throw profilesError;

      // Fetch user roles
      const { data: roles, error: rolesError } = await supabase.from("user_roles").select("*");

      if (rolesError) throw rolesError;

      // Fetch organizations
      const { data: orgs, error: orgsError } = await supabase
        .from("organizations")
        .select("id, name");

      if (orgsError) throw orgsError;

      setOrganizations(orgs || []);

      // Combine data
      const usersWithRoles = (profiles || []).map((profile) => {
        const userRole = roles?.find((r) => r.user_id === profile.user_id);
        const org = orgs?.find((o) => o.id === profile.organization_id);
        return {
          ...profile,
          generated_password: null,
          role: userRole?.role || null,
          organization_name: org?.name || null };
      });

      setUsers(usersWithRoles);
    } catch (error) {
      console.error("Error fetching users:", error);
      toast.error("Ошибка", { description: "Не удалось загрузить пользователей" });
    } finally {
      setLoading(false);
    }
  };

  const handleRoleChange = async (userId: string, newRole: "admin" | "organization" | "student") => {
    credentials.clear(userId);
    try {
      // Use secure RPC function for admin role management
      const { error } = await supabase.rpc('admin_update_user_role', {
        p_user_id: userId,
        p_new_role: newRole
      });

      if (error) throw error;

      setUsers((prev) =>
        prev.map((u) => (u.user_id === userId ? { ...u, role: newRole } : u))
      );

      toast.success("Успешно", { description: "Роль обновлена" });
    } catch (error: any) {
      console.error("Error updating role:", error);
      const errorMessage = error?.message?.includes("Cannot remove last admin") 
        ? "Нельзя удалить последнего администратора"
        : error?.message?.includes("Unauthorized") 
          ? "Недостаточно прав для изменения роли"
          : "Не удалось обновить роль";
      toast.error("Ошибка", { description: "errorMessage" });
    }
  };

  const handleOrgChange = async (userId: string, orgId: string | null) => {
    credentials.clear(userId);
    try {
      // Update profile
      const { error: profileError } = await supabase
        .from("profiles")
        .update({ organization_id: orgId })
        .eq("user_id", userId);

      if (profileError) throw profileError;

      const org = organizations.find((o) => o.id === orgId);
      setUsers((prev) =>
        prev.map((u) =>
          u.user_id === userId
            ? { ...u, organization_id: orgId, organization_name: org?.name || null }
            : u
        )
      );

      toast.success("Успешно", { description: "Организация обновлена" });
    } catch (error) {
      console.error("Error updating organization:", error);
      toast.error("Ошибка", { description: "Не удалось обновить организацию" });
    }
  };

  const handleDelete = async () => {
    if (!deleteUser) return;
    credentials.clear(deleteUser.user_id);

    try {
      // Delete user roles
      await supabase.from("user_roles").delete().eq("user_id", deleteUser.user_id);

      // Delete profile
      await supabase.from("profiles").delete().eq("user_id", deleteUser.user_id);

      // Note: We can't delete from auth.users from client - that would require admin API

      setUsers((prev) => prev.filter((u) => u.id !== deleteUser.id));
      toast.success("Успешно", { description: "Профиль пользователя удален" });
      setDeleteUser(null);
    } catch (error) {
      console.error("Error deleting user:", error);
      toast.error("Ошибка", { description: "Не удалось удалить пользователя" });
    }
  };

  const filteredUsers = users.filter((user) => {
    const matchesSearch =
      !searchQuery ||
      user.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      user.email?.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesRole = roleFilter === "all" || user.role === roleFilter;

    return matchesSearch && matchesRole;
  });

  const displayedUsers = filteredUsers.slice(0, visibleCount);
  const credentials = useExplicitUserCredential(displayedUsers, JSON.stringify([searchQuery, roleFilter, visibleCount]));
  useEffect(() => {
    if (credentials.failedVersion !== null) toast.error("Не удалось показать пароль. Повторите запрос.");
  }, [credentials.failedVersion]);

  // Reset visible count when filters change
  useEffect(() => {
    setVisibleCount(10);
  }, [searchQuery, roleFilter]);

  const stats = {
    total: users.length,
    admins: users.filter((u) => u.role === "admin").length,
    organizations: users.filter((u) => u.role === "organization").length,
    students: users.filter((u) => u.role === "student").length };

  if (loading) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-2xl font-display font-bold">Пользователи</h2>
          <p className="text-muted-foreground">Управление пользователями платформы</p>
        </div>
        <TableSkeleton rows={8} cols={6} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-display font-bold">Пользователи</h2>
        <p className="text-muted-foreground">Управление пользователями платформы</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardDescription>Всего</CardDescription>
            <CardTitle className="text-3xl">{stats.total}</CardTitle>
          </CardHeader>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-1">
              <Shield className="w-3 h-3" /> Админы
            </CardDescription>
            <CardTitle className="text-3xl">{stats.admins}</CardTitle>
          </CardHeader>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-1">
              <Building2 className="w-3 h-3" /> Организации
            </CardDescription>
            <CardTitle className="text-3xl">{stats.organizations}</CardTitle>
          </CardHeader>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-1">
              <GraduationCap className="w-3 h-3" /> Слушатели
            </CardDescription>
            <CardTitle className="text-3xl">{stats.students}</CardTitle>
          </CardHeader>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Поиск по имени или email..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-10"
          />
        </div>
        <Select value={roleFilter} onValueChange={setRoleFilter}>
          <SelectTrigger className="w-full sm:w-48">
            <SelectValue placeholder="Все роли" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Все роли</SelectItem>
            <SelectItem value="admin">Админы</SelectItem>
            <SelectItem value="organization">Организации</SelectItem>
            <SelectItem value="student">Слушатели</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Table */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Пользователь</TableHead>
                <TableHead>Учётные данные</TableHead>
                <TableHead>Роль</TableHead>
                <TableHead>Организация</TableHead>
                <TableHead>Дата регистрации</TableHead>
                <TableHead className="text-right">Действия</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredUsers.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="p-0">
                    <EmptyState
                      icon={Users}
                      title="Пользователи не найдены"
                      description="Попробуйте изменить фильтр роли или поисковый запрос."
                      className="border-0 rounded-none"
                    />
                  </TableCell>
                </TableRow>
              ) : (
                displayedUsers.map((user) => (
                  <UserTableRow
                    key={user.id}
                    user={user}
                    revealedPassword={credentials.passwordFor(user.user_id)}
                    organizations={organizations}
                    isPasswordVisible={credentials.passwordFor(user.user_id) !== null}
                    isPasswordLoading={credentials.pendingUserId === user.user_id}
                    onTogglePassword={togglePasswordVisibility}
                    onCopyCredentials={copyCredentials}
                    onRoleChange={handleRoleChange}
                    onOrgChange={handleOrgChange}
                    onViewAsStudent={viewAsStudent}
                    onDelete={(user) => {
                      credentials.clear(user.user_id);
                      setDeleteUser(user);
                    }}
                    onNavigate={(uid) => navigate(`/admin/user/${uid}`)}
                  />
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {filteredUsers.length > visibleCount && (
        <div className="flex items-center justify-between">
          <span className="text-sm text-muted-foreground">
            Показано {Math.min(visibleCount, filteredUsers.length)} из {filteredUsers.length}
          </span>
          <div className="flex items-center gap-2">
            <span className="text-sm text-muted-foreground">Показать ещё:</span>
            {[10, 25, 50, 100].map((n) => (
              <Button key={n} variant="outline" size="sm" onClick={() => setVisibleCount((prev) => prev + n)}>
                +{n}
              </Button>
            ))}
          </div>
        </div>
      )}
      {filteredUsers.length > 0 && filteredUsers.length <= visibleCount && (
        <div className="text-sm text-muted-foreground">
          Показано {filteredUsers.length} из {filteredUsers.length}
        </div>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteUser} onOpenChange={() => setDeleteUser(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Удалить пользователя?</AlertDialogTitle>
            <AlertDialogDescription>
              Вы уверены, что хотите удалить профиль пользователя "{deleteUser?.full_name || deleteUser?.email}"? 
              Это действие удалит профиль и роль пользователя.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Отмена</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">
              Удалить
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { TableRow, TableCell } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Trash2, Shield, Building2, GraduationCap, Copy, Eye, EyeOff, ExternalLink } from "lucide-react";
import { format } from "date-fns";
import { ru } from "date-fns/locale";

interface UserWithRole {
  id: string;
  user_id: string;
  full_name: string | null;
  email: string | null;
  avatar_url: string | null;
  organization_id: string | null;
  organization_name?: string | null;
  role: string | null;
  created_at: string;
  login: string | null;
  generated_password: string | null;
}

interface UserTableRowProps {
  user: UserWithRole;
  organizations: { id: string; name: string }[];
  isPasswordVisible: boolean;
  revealedPassword?: string | null;
  isPasswordLoading?: boolean;
  onTogglePassword: (userId: string) => void;
  onCopyCredentials: (userId: string) => void;
  onRoleChange: (userId: string, role: "admin" | "organization" | "student") => void;
  onOrgChange: (userId: string, orgId: string | null) => void;
  onViewAsStudent: (user: UserWithRole) => void;
  onDelete: (user: UserWithRole) => void;
  onNavigate: (userId: string) => void;
}

export function UserTableRow({
  user, organizations, isPasswordVisible, revealedPassword = null, isPasswordLoading = false, onTogglePassword, onCopyCredentials,
  onRoleChange, onOrgChange, onViewAsStudent, onDelete, onNavigate
}: UserTableRowProps) {
  return (
    <TableRow className="cursor-pointer hover:bg-secondary/50" onClick={() => onNavigate(user.user_id)}>
      <TableCell>
        <div className="flex items-center gap-3">
          <Avatar>
            <AvatarImage src={user.avatar_url || undefined} />
            <AvatarFallback>{user.full_name?.[0]?.toUpperCase() || user.email?.[0]?.toUpperCase() || "?"}</AvatarFallback>
          </Avatar>
          <div>
            <div className="font-medium">{user.full_name || "Без имени"}</div>
            <div className="text-sm text-muted-foreground">{user.email}</div>
          </div>
        </div>
      </TableCell>
      <TableCell>
        {user.role === 'student' && user.login ? (
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted-foreground">Логин:</span>
              <span className="text-sm font-mono">{user.login}</span>
            </div>
            {(
              <div className="flex items-center gap-1">
                <span className="text-xs text-muted-foreground">Пароль:</span>
                <span className="text-sm font-mono">{isPasswordVisible && revealedPassword ? revealedPassword : isPasswordLoading ? 'Загрузка…' : '••••••••'}</span>
                <Button variant="ghost" size="icon" className="h-5 w-5" aria-label={`${isPasswordVisible ? "Скрыть пароль" : isPasswordLoading ? "Отменить показ пароля" : "Показать пароль"} ${user.login}`} aria-busy={isPasswordLoading} onClick={(e) => { e.stopPropagation(); onTogglePassword(user.user_id); }}>
                  {isPasswordVisible || isPasswordLoading ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                </Button>
                <Button variant="ghost" size="icon" className="h-5 w-5" disabled={!isPasswordVisible || !revealedPassword} aria-label={`Скопировать показанные учётные данные ${user.login}`} onClick={(e) => { e.stopPropagation(); onCopyCredentials(user.user_id); }}>
                  <Copy className="w-3 h-3" />
                </Button>
